commands.command:
docker exec -i obfhb-pg-red psql -v ON_ERROR_STOP=1 -U open_brain -d open_brain_test <<'SQL'
WITH expected(table_name, column_name) AS (...expected bootstrap columns...), missing AS (SELECT * FROM expected EXCEPT SELECT table_name, column_name FROM information_schema.columns WHERE table_schema = 'public') SELECT COUNT(*) AS missing_expected_columns FROM missing;
WITH inserted AS (INSERT INTO memories (content, title, type, metadata) VALUES ('smoke content for bootstrap', 'Bootstrap Smoke', 'observation', '{"capture_status":"inbox"}'::jsonb) RETURNING id), rel AS (INSERT INTO memory_relationships (source_id, target_id, relation_type, link_type, confidence, metadata) SELECT id, id, 'similar_to', 'similar_to', 1.0, '{}'::jsonb FROM inserted ON CONFLICT (source_id, target_id, relation_type) DO UPDATE SET confidence = EXCLUDED.confidence RETURNING id), usage AS (INSERT INTO memory_usage_log (memory_id, event_type, session_context) SELECT id, 'retrieved', 'bootstrap-smoke' FROM inserted RETURNING id), priority AS (SELECT update_priority(id) FROM inserted), decay AS (SELECT decay_unused_priorities(0, 0.9) AS affected), hybrid AS (SELECT COUNT(*)::int AS matches FROM hybrid_search('bootstrap smoke', NULL::vector, 5, 60, NULL, NULL, NULL, NULL)) SELECT (SELECT COUNT(*) FROM inserted) AS inserted_memories, (SELECT COUNT(*) FROM rel) AS inserted_relationships, (SELECT COUNT(*) FROM usage) AS inserted_usage_events, (SELECT affected FROM decay) AS decay_affected, (SELECT matches FROM hybrid) AS hybrid_matches;
SQL
